import { useEffect, useState } from "react";
import "./App.css";

function App() {
  const [sec, setSec] = useState(0);
  const [min,setMin] = useState(0)

  useEffect(() => {
    const intervalSec = setInterval(() => {
      setSec((prevState) => prevState===59 ? prevState=0: prevState + 1);
    }, 1000);
    const intervalMin = setInterval(()=>{
      setMin((prevState)=> prevState===59 ? prevState=0 : prevState+1)
    }, 60000)

    return () => clearInterval(intervalSec);
    return () => clearInterval(intervalMin);

  }, []);

  return <div>{sec<10 ? `0${sec}` : sec} seconds {}</div>;
}

export default App;
